fn largest_power_of_two_le(n: i8) -> i8 {
    let mut power = 1;
    while power <= n {
        power *= 2;
    }
    power / 2 // Return the largest power of two that is less than or equal to n
}

fn solve(n: i8) -> i8 {
    if n % 2 != 0 { // Check if n is odd
        (n - 1) / 2
    } else { // n is even
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

